ValidationRule.errorConditionFormula:
OR(
    ISBLANK(TEXT(Status__c)),
    AND(
        ISNEW(),
        NOT(ISPICKVAL(Status__c, "Draft"))
    ),
    AND(
        NOT(ISNEW()),
        ISCHANGED(Status__c),
        OR(
            AND(
                ISPICKVAL(PRIORVALUE(Status__c), "Draft"),
                NOT(ISPICKVAL(Status__c, "Review"))
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status__c), "Review"),
                NOT(
                    OR(
                        ISPICKVAL(Status__c, "Draft"),
                        ISPICKVAL(Status__c, "Approved")
                    )
                )
            )
        )
    )
)
